{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service Version 1 is enabled",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "MEDIUM",
      "explanation": "The launch template does not require IMDS session tokens, allowing instances to use the less secure IMDSv1 and increasing the risk of credential theft through server-side request forgery."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"changeme_simple_asg_launch_template_nlb\" {\n  name                   = \"changeme-simple-asg-launch-template-nlb\"\n  image_id               = data.aws_ami.changeme_amazon_nlb_ami.id\n  instance_type          = \"t2.micro\"\n  vpc_security_group_ids = [aws_security_group.changeme_nlb_aws_security_group.id]\n  user_data              = filebase64(\"${path.module}/user_data.sh\")\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}\n",
  "fix_summary": "Added launch template metadata options requiring IMDSv2 session tokens, which prevents use of IMDSv1."
}
